function draw({board,width,height,progress,params}) {
  const P=VisualBook.palette, p=progress, w=params.w;
  const x=[0,1,2,3], y=x.map(t=>t*t), seed=[1,1,1,w], g=x.map((t,i)=>2*t*seed[i]);
  const L=36, R=width-32, M=(L+R)/2, Y=50, dy=50;
  const fmt=t=>Number(t.toFixed(2)).toString();
  board.text('head-x','输入 x',L,20,{size:14,color:P.muted});
  board.text('head-y','y = x²',M,20,{size:14,color:P.muted,anchor:'middle'});
  board.text('head-v','种子 v',R,20,{size:14,color:P.muted,anchor:'end'});
  for(let i=0;i<4;i++) {
    const yy=Y+i*dy;
    board.line('forward-'+i,L+26,yy,M-30,yy,P.faint,1.5,1);
    board.mark('head-'+i,'path',{d:`M ${M-34} ${yy-3} L ${M-28} ${yy} L ${M-34} ${yy+3}`,fill:'none',stroke:P.muted,'stroke-width':1});
    board.line('seed-edge-'+i,R-18,yy+12,M+24,yy+12,P.orange,1.3,.4);
    board.line('reverse-'+i,M-22,yy+12,L+12,yy+12,P.orange,1.3,.4);
    board.text('x-'+i,fmt(x[i]),L,yy,{size:18,color:P.ink});
    board.text('y-'+i,fmt(y[i]),M,yy,{size:18,color:P.blue,anchor:'middle'});
    board.text('v-'+i,fmt(seed[i]),R,yy,{size:18,color:P.orange,anchor:'end'});
    board.text('local-'+i,'×'+fmt(2*x[i]),(L+M)/2,yy+31,{size:12,color:P.orange,anchor:'middle'});
    board.line('bridge-'+i,M+24,yy+12,M-22,yy+12,P.orange,1.3,.4);
    const px=(R-18)+(L+12-(R-18))*p;
    board.mark('reverse-head-'+i,'path',{d:`M ${L+18} ${yy+9} L ${L+12} ${yy+12} L ${L+18} ${yy+15}`,fill:'none',stroke:P.orange,'stroke-width':1.2});
    board.circle('pulse-'+i,px,yy+12,3.5,P.orange);
  }
  board.line('separator',24,252,width-24,252,P.faint,1,1);
  const scalar=seed.reduce((s,v,i)=>s+v*y[i],0);
  board.text('result','Jᵀv = ('+g.map(fmt).join(', ')+')',24,281,{size:17,color:P.orange});
  board.text('jacobian','J = diag(0, 2, 4, 6)',24,308,{size:14,color:P.muted});
  board.text('sum','对应标量  Σ vᵢ yᵢ = '+fmt(scalar),24,334,{size:14,color:P.muted});
  return {x,y,seed,jacobianDiagonal:x.map(t=>2*t),gradient:g,weightedScalar:scalar,markerProgress:p,interpretation:'移动的是反传信号；梯度数值不做插值'};
}

function draw({board,width,height,progress,params}) {
  const P=VisualBook.palette, x=params.x, u=x*x, z=u*x, p=progress;
  const fmt=t=>Number(t.toFixed(2)).toString();
  const L=32,R=width-32,M=(L+R)/2;
  function pathPoint(points,t) {
    const lengths=points.slice(1).map((q,i)=>Math.hypot(q[0]-points[i][0],q[1]-points[i][1]));
    let d=t*lengths.reduce((a,b)=>a+b,0);
    for(let i=0;i<lengths.length;i++){if(d<=lengths[i]||i===lengths.length-1){const s=lengths[i]===0?0:d/lengths[i];return [points[i][0]+s*(points[i+1][0]-points[i][0]),points[i][1]+s*(points[i+1][1]-points[i][1])];}d-=lengths[i];}
  }
  function route(id,pts,color,opacity) {
    board.mark(id,'path',{d:pts.map((q,i)=>(i?'L ':'M ')+q.join(' ')).join(' '),fill:'none',stroke:color,'stroke-width':1.6,opacity});
  }
  for(let row=0;row<2;row++) {
    const base=35+row*166, isDetached=row===1;
    const A=[L,base+53],B=[M,base+21],C=[R,base+53];
    board.text('mode-'+row,isDetached?'分离 u':'保留计算图',18,base-12,{size:14,color:P.ink,weight:600});
    route('forward-'+row,[[L+22,A[1]-5],[M-25,B[1]+8]],P.muted,.4);
    route('edge-right-'+row,[[M+25,B[1]+8],[R-22,C[1]-5]],P.muted,.4);
    const direct=[[R-12,C[1]+12],[R-30,base+92],[L+30,base+92],[L+12,A[1]+12]];
    route('direct-'+row,direct,P.blue,.55);
    const cut=[(L+M)/2,(A[1]+B[1])/2];
    const via=[[R-22,C[1]-5],[M+25,B[1]+8],[M-25,B[1]+8],isDetached?cut:[L+22,A[1]-5]];
    route('back-'+row,via,P.orange,.65);
    board.text('x-'+row,'x='+fmt(x),L,A[1],{size:14,color:P.ink,anchor:'middle'});
    board.text('u-'+row,(isDetached?'u':'x²')+'='+fmt(u),M,B[1],{size:14,color:P.ink,anchor:'middle'});
    board.text('z-'+row,'z='+fmt(z),R,C[1],{size:14,color:P.ink,anchor:'middle'});
    board.text('via-value-'+row,isDetached?'截断：0':'2x²='+fmt(2*u),(L+M)/2,base+4,{size:12,color:P.orange,anchor:'middle'});
    board.text('direct-value-'+row,'直接项 x²='+fmt(u),M,base+83,{size:12,color:P.blue,anchor:'middle'});
    if(isDetached) {
      board.line('cut-a',cut[0]-5,cut[1]-6,cut[0]+5,cut[1]+6,P.orange,2,1);
      board.line('cut-b',cut[0]-5,cut[1]+6,cut[0]+5,cut[1]-6,P.orange,2,1);
    }
    const d=pathPoint(direct,p),v=pathPoint(via,p);
    board.circle('direct-pulse-'+row,d[0],d[1],3.5,P.blue);
    board.circle('via-pulse-'+row,v[0],v[1],3.5,P.orange);
    board.text('gradient-'+row,'∂z/∂x = '+fmt(isDetached?u:3*u),M,base+123,{size:17,color:P.ink,anchor:'middle'});
  }
  board.line('divider',18,181,width-18,181,P.faint,1,1);
  return {x,u,z,fullGradient:3*u,detachedGradient:u,directContribution:u,viaContribution:2*u,detachedViaContribution:0,markerProgress:p};
}

function draw({board,width,height,progress,params}) {
  const P=VisualBook.palette, a=params.a, s=a-20+40*progress;
  function run(t) {let b=2*t,loops=0,k=2;while(Math.abs(b)<1000){b*=2;k*=2;loops++;}if(b<=0){b*=100;k*=100;}return {value:b,loops,recordedSlope:k};}
  const v=run(s), fmt=t=>Number(t.toFixed(2)).toString();
  const frame=board.axes('f-axis',{xDomain:[240,760],yDomain:[0,2150],box:[50,24,width-20,height-108],xLabel:'输入 s',yLabel:'f(s)',grid:false});
  board.curve('left-branch',frame,[[250,1000],[500,2000]],{color:P.blue,width:2});
  board.curve('right-branch',frame,[[500,1000],[760,1520]],{color:P.blue,width:2});
  board.mark('open-boundary','circle',{cx:frame.x(500),cy:frame.y(2000),r:4,fill:P.paper,stroke:P.blue,'stroke-width':1.8});
  board.circle('closed-boundary',frame.x(500),frame.y(1000),4,P.blue);
  board.text('left-slope','斜率 4',frame.x(320),frame.y(1720),{size:13,color:P.muted});
  board.text('right-slope','斜率 2',frame.x(570),frame.y(850),{size:13,color:P.muted});
  board.mark('jump-line','path',{d:`M ${frame.x(500)} ${frame.y(0)} L ${frame.x(500)} ${frame.y(1950)}`,fill:'none',stroke:P.faint,'stroke-width':1.2,'stroke-dasharray':'3 4'});
  if(width<500) board.text('boundary-tick','500',frame.x(500),frame.y(0)+20,{size:12,color:P.muted,anchor:'middle'});
  board.line('probe-line',frame.x(s),frame.y(0),frame.x(s),frame.y(v.value),P.orange,1,.6);
  const dx=18, lo=s<500?Math.max(250,s-dx):Math.max(500,s-dx), hi=s<500?Math.min(500,s+dx):Math.min(760,s+dx);
  board.curve('recorded-tangent',frame,[[lo,v.value+v.recordedSlope*(lo-s)],[hi,v.value+v.recordedSlope*(hi-s)]],{color:P.orange,width:2});
  board.circle('probe',frame.x(s),frame.y(v.value),4,P.orange);
  board.text('execution','s='+fmt(s)+' · while '+v.loops+' 次 · f='+fmt(v.value),18,height-61,{size:14,color:P.ink});
  board.text('slope-readout',s===500?'s=500：跳变；路径记录斜率 2':'本次路径斜率  '+v.recordedSlope,18,height-33,{size:14,color:P.orange});
  return {center:a,probe:s,probeRange:[a-20,a+20],output:v.value,whileIterations:v.loops,recordedSlope:v.recordedSlope,classicalDerivative:s===500?null:v.recordedSlope,discontinuity:500,positiveScalarSlice:true};
}
